SELECT id, name, channel_id, enabled, created_at, updated_at
FROM creators


        AND channel_id = #{channelId}


        AND enabled = #{enabled}


        AND name LIKE CONCAT('%', #{name}, '%')


ORDER BY channel_id, name, id

SELECT id, name, channel_id, enabled, created_at, updated_at
FROM creators
WHERE id = #{id}
